export interface InvoicePdfData {

garageName: string;
  ownerName?: string;
  garageAddress: string;
  garagePhone: string;
  garageEmail: string;

 gstNumber: string;
  garageTagline: string;
  invoiceNumber: string;
  invoiceDate: string;
  paymentDate?: 
string;
  customerName: string;
  customerPhone: string;
  customerAddress: string;
  vehicleReg: string;

vehicleBrand: string;
  vehicleModel: string;
  laborItems: { description: string; hours: number; rate: number; 
total: number }[];
  partItems: { partName: string; quantity: number; unitPrice: number; total: number }[];

laborTotal: number;
  partsTotal: number;
  subtotal: number;
  taxRate: number;
  taxAmount: number;

discountAmount: number;
  grandTotal: number;
  amountPaid: number;
  cashAmount?: number;
  upiAmount?: number;

 paymentMethod?: string;
  paymentStatus: string;
  upiQrDataUrl?: string;
  upiVpa?: string;
  theme?: string; // 
"default", "modern", "minimal", "bold", "sunset", "purple", "teal", "slate"
  format?: string; // 
"classic_boxed", "centered_pro", "grid_structured", "modern_accent"
}

function formatCurrency(amount: 
number): string {
  return `Rs. ${amount.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 
2 })}`;
}

export async function generateInvoicePdf(
  data: InvoicePdfData
): Promise<Uint8Array> {
  const 
formatStr = data.format || "classic_boxed";

  if (formatStr === "centered_pro") {
    return 
generateCenteredProfessional(data);
  } else if (formatStr === "grid_structured") {
    return 
generateGridStructured(data);
  } else if (formatStr === "modern_accent") {
    return 
generateModernAccent(data);
  } else {
    return generateClassicBoxed(data);
  }
}

// â”€â”€â”€ Theme Colors 
Helper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â
”€â”€â”€â”€â”€â”€â”€â”€â”€
function getThemeColors(themeStr: string) {
  let primaryColor = rgb(0.1, 0.5, 0.3); // 
Deep Green (default)
  let secondaryColor = rgb(0.98, 0.98, 0.98);
  let textColor = rgb(0.2, 0.2, 0.2);
  let 
mutedColor = rgb(0.4, 0.4, 0.4);
  let lightGray = rgb(0.95, 0.95, 0.95);
  let borderColor = rgb(0.85, 0.85, 
0.85);
  let headerTextColor = primaryColor;
  let tableHeaderBg = primaryColor;
  let tableHeaderTextColor = 
rgb(1,1,1);
  let showBorders = true;
  let borderWidth = 1;

  if (themeStr === "modern") {
    primaryColor = 
rgb(0.15, 0.38, 0.82); // Blue
    headerTextColor = rgb(0.1, 0.1, 0.1);
    tableHeaderBg = rgb(0.92, 0.95, 
0.99);
    tableHeaderTextColor = rgb(0.1, 0.1, 0.2);
    borderColor = rgb(0.9, 0.9, 0.9);
  } else if (themeStr 
=== "minimal") {
    primaryColor = rgb(0.1, 0.1, 0.1); // Black
    headerTextColor = rgb(0.1, 0.1, 0.1);

tableHeaderBg = rgb(1, 1, 1);
    tableHeaderTextColor = rgb(0.1, 0.1, 0.1);
    secondaryColor = rgb(1, 1, 1);

lightGray = rgb(1, 1, 1);
    showBorders = false;
  } else if (themeStr === "bold") {
    primaryColor = 
rgb(0.8, 0.2, 0.2); // Red
    headerTextColor = rgb(0.8, 0.2, 0.2);
    tableHeaderBg = rgb(0.1, 0.1, 0.1);

tableHeaderTextColor = rgb(1, 1, 1);
    borderColor = rgb(0.1, 0.1, 0.1);
    secondaryColor = rgb(0.96, 0.96, 
0.96);
    borderWidth = 2;
  } else if (themeStr === "sunset") {
    primaryColor = rgb(0.85, 0.45, 0.15); // 
Orange
    headerTextColor = rgb(0.8, 0.4, 0.1);
    tableHeaderBg = rgb(1, 0.95, 0.9);
    tableHeaderTextColor = 
rgb(0.3, 0.15, 0);
    borderColor = rgb(0.95, 0.8, 0.7);
  } else if (themeStr === "purple") {
    primaryColor 
= rgb(0.5, 0.25, 0.7); // Purple
    headerTextColor = rgb(0.4, 0.15, 0.6);
    tableHeaderBg = rgb(0.96, 0.92, 
1);
    tableHeaderTextColor = rgb(0.2, 0.05, 0.3);
    borderColor = rgb(0.85, 0.75, 0.95);
  } else if (themeStr 
=== "teal") {
    primaryColor = rgb(0.1, 0.6, 0.6); // Teal
    headerTextColor = rgb(0.05, 0.5, 0.5);

tableHeaderBg = rgb(0.9, 0.98, 0.98);
    tableHeaderTextColor = rgb(0, 0.25, 0.25);
    borderColor = rgb(0.7, 0.9, 
0.9);
  } else if (themeStr === "slate") {
    primaryColor = rgb(0.3, 0.35, 0.4); // Slate
    headerTextColor = 
rgb(0.2, 0.25, 0.3);
    tableHeaderBg = rgb(0.94, 0.95, 0.96);
    tableHeaderTextColor = rgb(0.1, 0.15, 0.2);

borderColor = rgb(0.8, 0.85, 0.9);
  }

  return { primaryColor, secondaryColor, textColor, mutedColor, lightGray, 
borderColor, headerTextColor, tableHeaderBg, tableHeaderTextColor, showBorders, borderWidth };
}

