const drawRightText = (page: PDFPage, text: string, xPos: number, 
yPos: number, size: number, font: PDFFont, color: any) => {
  const textWidth = font.widthOfTextAtSize(text, size);

 page.drawText(text, { x: xPos - textWidth, y: yPos, size, font, color });
};

const drawCenterText = (page: 
PDFPage, text: string, yPos: number, size: number, font: PDFFont, color: any, width: number) => {
  const textWidth = 
font.widthOfTextAtSize(text, size);
  page.drawText(text, { x: (width - textWidth) / 2, y: yPos, size, font, color 
});
};

async function drawPaymentInfoAndFooter(pdfDoc: PDFDocument, page: PDFPage, data: InvoicePdfData, margin: 
number, width: number, startY: number, fontRegular: PDFFont, fontBold: PDFFont, colors: any, withWatermark = false) 
{
  let leftY = startY;

  if (withWatermark && data.paymentStatus === "paid") {
    // Draw rotated stamp

 page.drawText("PAID IN FULL", { 
      x: margin + 30, y: leftY - 40, size: 40, font: fontBold, 
      color: 
rgb(0.2, 0.7, 0.3), opacity: 0.2, rotate: degrees(25) 
    });
  }

  if (data.paymentStatus === "paid") {

page.drawText("PAID IN FULL", { x: margin, y: leftY - 15, size: 16, font: fontBold, color: rgb(0.2, 0.7, 0.3) });

  leftY -= 35;
    if ((data.cashAmount && data.cashAmount > 0) || (data.upiAmount && data.upiAmount > 0)) {

if (data.cashAmount && data.cashAmount > 0) { page.drawText(`Via Cash: ${formatCurrency(data.cashAmount)}`, { x: 
margin, y: leftY, size: 10, font: fontRegular, color: colors.textColor }); leftY -= 14; }
      if (data.upiAmount && 
data.upiAmount > 0) { page.drawText(`Via UPI: ${formatCurrency(data.upiAmount)}`, { x: margin, y: leftY, size: 10, 
font: fontRegular, color: colors.textColor }); leftY -= 14; }
    }
  } else if (data.paymentStatus === "partial" 
&& data.amountPaid > 0) {
    const balanceDue = data.grandTotal - data.amountPaid;
    page.drawText("PARTIALLY 
PAID", { x: margin, y: leftY - 15, size: 14, font: fontBold, color: rgb(0.9, 0.55, 0.1) });
    leftY -= 35;

page.drawText(`Paid: ${formatCurrency(data.amountPaid)}`, { x: margin, y: leftY, size: 10, font: fontRegular, color: 
rgb(0.15, 0.55, 0.3) });
    leftY -= 15;
    page.drawText(`Balance Due: ${formatCurrency(balanceDue)}`, { x: 
margin, y: leftY, size: 10, font: fontBold, color: rgb(0.7, 0.15, 0.15) });
    leftY -= 20;
  } else if 
(data.paymentStatus === "unpaid") {
    page.drawText("UNPAID", { x: margin, y: leftY - 15, size: 16, font: 
fontBold, color: rgb(0.8, 0.2, 0.2) });
    leftY -= 30;
  }

  // QR Code
  if (data.upiQrDataUrl && data.upiVpa 
&& data.paymentStatus !== "paid") {
    const qrSize = 60;
    try {
      const base64Data = 
data.upiQrDataUrl.split(",")[1];
      if (base64Data) {
        const qrImageBytes = 
Uint8Array.from(atob(base64Data), (c) => c.charCodeAt(0));
        const qrImage = await 
pdfDoc.embedPng(qrImageBytes);
        page.drawImage(qrImage, { x: margin, y: leftY - qrSize, width: qrSize, height: 
qrSize });
        page.drawText("Scan to Pay", { x: margin + qrSize + 10, y: leftY - 15, size: 9, font: fontBold, 
color: colors.textColor });
        page.drawText(`UPI ID: ${data.upiVpa}`, { x: margin + qrSize + 10, y: leftY - 28, 
size: 8, font: fontRegular, color: colors.mutedColor });
      }
    } catch {}
  }

  // Footer

page.drawText("Authorized Signature", { x: width - margin - 110, y: 50, size: 10, font: fontRegular, color: 
colors.textColor });
  page.drawLine({ start: { x: width - margin - 130, y: 65 }, end: { x: width - margin, y: 65 }, 
thickness: 1, color: colors.textColor });
  page.drawText("Thank you for your business!", { x: margin, y: 30, size: 
10, font: fontBold, color: colors.primaryColor });
}


// â”€â”€â”€ 1. Classic Boxed Format (Image 1) 
â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
async function 
generateClassicBoxed(data: InvoicePdfData) {
  const pdfDoc = await PDFDocument.create();
  const page = 
pdfDoc.addPage([595, 842]);
  const fontRegular = await pdfDoc.embedFont(StandardFonts.Helvetica);
  const fontBold 
= await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const { width, height } = page.getSize();
  const margin = 
40;
  let y = height - margin;
  const colors = getThemeColors(data.theme || "default");

  // Logo Placeholder 
& Header
  page.drawText(data.garageName.toUpperCase(), { x: margin, y: y - 10, size: 20, font: fontBold, color: 
colors.headerTextColor });
  y -= 25;
  if (data.ownerName) { page.drawText(`Proprietor: ${data.ownerName}`, { x: 
margin, y, size: 10, font: fontBold, color: colors.textColor }); y -= 14; }
  if (data.garageAddress) { 
page.drawText(data.garageAddress, { x: margin, y, size: 9, font: fontRegular, color: colors.mutedColor }); y -= 14; 
}
  const contactParts = [data.garagePhone, data.garageEmail].filter(Boolean);
  if (contactParts.length) { 
page.drawText(contactParts.join(" | "), { x: margin, y, size: 9, font: fontRegular, color: colors.mutedColor }); y 
-= 14; }
  if (data.gstNumber) { page.drawText(`GSTIN: ${data.gstNumber}`, { x: margin, y, size: 9, font: fontBold, 
color: colors.textColor }); }

  let invY = height - margin - 10;
  drawRightText(page, "TAX INVOICE", width - 
margin, invY, 22, fontBold, colors.textColor);
  invY -= 22;
  drawRightText(page, `Invoice No: 
${data.invoiceNumber}`, width - margin, invY, 10, fontRegular, colors.textColor);
  invY -= 14;

drawRightText(page, `Created: ${data.invoiceDate}`, width - margin, invY, 10, fontRegular, colors.textColor);
  if 
(data.paymentDate && data.paymentStatus === "paid") {
    invY -= 14;
    drawRightText(page, `Paid On: 
${data.paymentDate}`, width - margin, invY, 10, fontRegular, rgb(0.2, 0.6, 0.3));
  }

  y = Math.min(y - 20, invY 
- 20);

  // Boxed Info
  const boxWidth = (width - (margin * 2) - 20) / 2;
  page.drawRectangle({ x: margin, y: y 
- 80, width: boxWidth, height: 80, borderColor: colors.primaryColor, borderWidth: 1 });
  page.drawRectangle({ x: 
margin + boxWidth + 20, y: y - 80, width: boxWidth, height: 80, borderColor: colors.primaryColor, borderWidth: 1 });


  // Box titles with background clip
  page.drawRectangle({ x: margin + 10, y: y - 10, width: 50, height: 20, 
color: rgb(1,1,1) });
  page.drawText("BILL TO", { x: margin + 15, y: y - 5, size: 10, font: fontBold, color: 
colors.textColor });

  page.drawRectangle({ x: margin + boxWidth + 30, y: y - 10, width: 100, height: 20, color: 
rgb(1,1,1) });
  page.drawText("VEHICLE DETAILS", { x: margin + boxWidth + 35, y: y - 5, size: 10, font: fontBold, 
color: colors.textColor });

  let b1Y = y - 25;
  page.drawText(data.customerName, { x: margin + 10, y: b1Y, size: 
11, font: fontBold, color: colors.textColor }); b1Y -= 16;
  if (data.customerAddress) { 
page.drawText(data.customerAddress.substring(0, 45), { x: margin + 10, y: b1Y, size: 9, font: fontRegular, color: 
colors.textColor }); b1Y -= 14; }
  page.drawText(`Phone: ${data.customerPhone}`, { x: margin + 10, y: b1Y, size: 9, 
font: fontRegular, color: colors.textColor });

  let b2Y = y - 25;
  page.drawText(`${data.vehicleBrand} 
${data.vehicleModel}`.trim(), { x: margin + boxWidth + 30, y: b2Y, size: 11, font: fontBold, color: colors.textColor 
}); b2Y -= 16;
  page.drawText(`Reg No: ${data.vehicleReg}`, { x: margin + boxWidth + 30, y: b2Y, size: 9, font: 
fontRegular, color: colors.textColor });

  y -= 110;

  // Tables
  const drawTable = (title: string, items: 
any[], type: "labor" | "parts") => {
    if (items.length === 0) return;
    page.drawText(title, { x: margin, 
y, size: 11, font: fontBold, color: colors.textColor });
    y -= 15;
    // Header row background

page.drawRectangle({ x: margin, y: y - 5, width: width - (margin * 2), height: 18, color: rgb(0.92, 0.92, 0.92) });

  const cDesc = margin + 5;
    const cQty = margin + 300;
    const cRate = margin + 380;
    const cAmt = width - 
margin - 5;
    page.drawText(type === "labor" ? "Description" : "Part Name", { x: cDesc, y, size: 9, font: 
fontBold, color: colors.textColor });
    if (type === "parts") {
      drawRightText(page, "Qty", cQty, y, 9, 
fontBold, colors.textColor);
      drawRightText(page, "Rate", cRate, y, 9, fontBold, colors.textColor);
    }

 drawRightText(page, "Total", cAmt, y, 9, fontBold, colors.textColor);
    y -= 18;

    items.forEach((item, 
index) => {
      if (index % 2 !== 0) {
        page.drawRectangle({ x: margin, y: y - 5, width: width - (margin * 
2), height: 18, color: rgb(0.96, 0.96, 0.96) });
      }
      const desc = type === "labor" ? item.description : 
item.partName;
      page.drawText(desc.substring(0, 50), { x: cDesc, y, size: 9, font: fontRegular, color: 
colors.textColor });
      if (type === "parts") {
        drawRightText(page, `${item.quantity}`, cQty, y, 9, 
fontRegular, colors.textColor);
        drawRightText(page, formatCurrency(item.unitPrice), cRate, y, 9, fontRegular, 
colors.textColor);
      }
      drawRightText(page, formatCurrency(item.total), cAmt, y, 9, fontBold, 
colors.textColor);
      y -= 18;
    });
    y -= 15;
  };

  drawTable("LABOR CHARGES", data.laborItems, 
"labor");
  drawTable("SPARE PARTS", data.partItems, "parts");

  // Totals Box
  const totalsBoxWidth = 
220;
  const totalsX = width - margin - totalsBoxWidth;
  page.drawRectangle({ x: totalsX, y: y - 105, width: 
totalsBoxWidth, height: 115, borderColor: colors.primaryColor, borderWidth: 1 });

  let totY = y - 15;
  const 
drawSummaryRow = (label: string, value: string, bold = false) => {
    const f = bold ? fontBold : fontRegular;

page.drawText(label, { x: totalsX + 10, y: totY, size: 10, font: f, color: colors.textColor });

drawRightText(page, value, totalsX + totalsBoxWidth - 10, totY, 10, f, colors.textColor);
    totY -= 18;
  };


 drawSummaryRow("Labor Total", formatCurrency(data.laborTotal));
  drawSummaryRow("Parts Total", 
formatCurrency(data.partsTotal));
  drawSummaryRow("Subtotal", formatCurrency(data.subtotal), true);
  if 
(data.taxRate > 0) drawSummaryRow(`Tax (${data.taxRate}%)`, formatCurrency(data.taxAmount));
  if 
(data.discountAmount > 0) drawSummaryRow("Discount", `-${formatCurrency(data.discountAmount)}`);


page.drawRectangle({ x: totalsX, y: totY - 5, width: totalsBoxWidth, height: 25, color: rgb(1, 0.94, 0.94) });

page.drawLine({ start: { x: totalsX, y: totY - 5 + 25 }, end: { x: totalsX + totalsBoxWidth, y: totY - 5 + 25 }, 
thickness: 1, color: colors.primaryColor });
  page.drawText("GRAND TOTAL", { x: totalsX + 10, y: totY + 2, size: 
11, font: fontBold, color: colors.primaryColor });
  drawRightText(page, formatCurrency(data.grandTotal), totalsX + 
totalsBoxWidth - 10, totY + 2, 11, fontBold, colors.primaryColor);

  await drawPaymentInfoAndFooter(pdfDoc, page, 
data, margin, width, y - 10, fontRegular, fontBold, colors);
  return pdfDoc.save();
}

